{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Inclusion criteria: (1) Studies involving LSTs with lesions measuring > 20 mm; (2) Comparative studies reporting primary and secondary outcomes of ESD versus EMR. Exclusion criteria: (1) Studies including LSTs < 20 mm or other lesions preventing outcome extraction; ... (3) Case reports/series or studies with < 30 patients per ESD/EMR group; (4) Animal studies.",
      "reason": "Eligibility criteria specify population (colorectal LSTs > 20 mm), study design (comparative ESD vs EMR studies, with minimum group size of 30 patients), and outcome reporting requirements."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Exclusion criteria: (1) Studies including LSTs < 20 mm or other lesions preventing outcome extraction; (2) Reviews, meta-analyses, letters, editorials; (3) Case reports/series or studies with < 30 patients per ESD/EMR group; (4) Animal studies.",
      "reason": "Publication/report status is addressed (reviews, meta-analyses, letters, editorials, case reports/series excluded), but no language restrictions or dissemination year limits are reported; the search was 'from inception to 1 May 2025' with no language criterion stated."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": "text_3",
      "quote": "Studies including LSTs < 20 mm or other lesions preventing outcome extraction",
      "reason": "The manuscript does not distinguish between excluding studies because outcomes were not measured versus outcomes measured but results not reported; exclusion only mentions lesions 'preventing outcome extraction'."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Comparative studies reporting primary and secondary outcomes of ESD versus EMR",
      "reason": "The synthesis groups (ESD vs EMR/PEMR) are clearly specified and directly linked to the review objective comparing ESD versus EMR for colorectal LSTs > 20 mm; outcomes (recurrence, bleeding, perforation) are analyzed by these groups."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "For lesions larger than 20 mm, EMR often necessitates piecemeal resection (PEMR), whereas ESD enables en bloc resection [6]. ... However, for LSTs exceeding 20 mm in diameter, the optimal choice between ESD and EMR remains controversial [6-9].",
      "reason": "A rationale for the > 20 mm restriction is provided: at this size EMR requires piecemeal resection while ESD allows en bloc resection, and the optimal technique remains controversial."
    }
  ],
  "confidence": 88
}

